import{_ as r,o as e,c as a,ag as o}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"周刊#401 工具收录","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-tools/weekly-tools-401.md","filePath":"topics/ai-tools/weekly-tools-401.md"}'),d={name:"topics/ai-tools/weekly-tools-401.md"};function i(n,t,h,s,l,g){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="周刊-401-工具收录" tabindex="-1">周刊#401 工具收录 <a class="header-anchor" href="#周刊-401-工具收录" aria-label="Permalink to &quot;周刊#401 工具收录&quot;">​</a></h1><blockquote><p>来源：科技爱好者周刊第401期（2026-06-26）</p></blockquote><h2 id="开发工具" tabindex="-1">开发工具 <a class="header-anchor" href="#开发工具" aria-label="Permalink to &quot;开发工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td><strong>Lore</strong></td><td>Epic Games 开源版本管理系统，二进制文件拆成数据块，每次提交只存变更块。Git 管代码，Lore 管资源</td><td><a href="https://github.com/EpicGames/lore" target="_blank" rel="noreferrer">github.com/EpicGames/lore</a></td></tr><tr><td><strong>GitFolio</strong></td><td>轻量级 Git 仓库管理系统，类似 Gitea，支持从 GitHub 镜像同步</td><td><a href="https://github.com/azhai/gitfolio" target="_blank" rel="noreferrer">github.com/azhai/gitfolio</a></td></tr><tr><td><strong>JSOS</strong></td><td>基于 WebContainer 技术，浏览器里跑完整 Node.js 运行时，数据/代码存本地</td><td><a href="https://jsos.dev/" target="_blank" rel="noreferrer">jsos.dev</a></td></tr><tr><td><strong>DNS Pick</strong></td><td>命令行 DNS 优选工具，结合延迟与解析成功率选出最优 DNS</td><td><a href="https://github.com/palemoky/dnspick" target="_blank" rel="noreferrer">github.com/palemoky/dnspick</a></td></tr></tbody></table><h2 id="效率工具" tabindex="-1">效率工具 <a class="header-anchor" href="#效率工具" aria-label="Permalink to &quot;效率工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td><strong>ssh-at</strong></td><td>~/.ssh/config 图形化管理工具</td><td><a href="https://github.com/baerwang/ssh-at" target="_blank" rel="noreferrer">github.com/baerwang/ssh-at</a></td></tr><tr><td><strong>LockIME</strong></td><td>macOS 输入法锁定，按应用指定默认输入法</td><td><a href="https://github.com/oomol-lab/LockIME" target="_blank" rel="noreferrer">github.com/oomol-lab/LockIME</a></td></tr><tr><td><strong>AnyDrag</strong></td><td>macOS 窗口工具，不必按标题栏就能拖拽、缩放、平铺</td><td><a href="https://github.com/XueshiQiao/AnyDrag" target="_blank" rel="noreferrer">github.com/XueshiQiao/AnyDrag</a></td></tr><tr><td><strong>PowerLens</strong></td><td>Oh-My-Zsh 插件，命令行提示符实时展示电源功率、CPU温度、风扇转速、内存和网络流量</td><td><a href="https://github.com/luyangkk/powerlens" target="_blank" rel="noreferrer">github.com/luyangkk/powerlens</a></td></tr><tr><td><strong>MyKVM</strong></td><td>跨平台软件 KVM，同局域网内 macOS/Win/Linux 共享一套键鼠和剪贴板</td><td><a href="https://github.com/XxMinor/mykvm" target="_blank" rel="noreferrer">github.com/XxMinor/mykvm</a></td></tr></tbody></table><h2 id="ai-工具" tabindex="-1">AI 工具 <a class="header-anchor" href="#ai-工具" aria-label="Permalink to &quot;AI 工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td><strong>Fishword</strong></td><td>编程代理 Pi 插件，等待 AI 生成代码时弹出背单词窗口</td><td><a href="https://github.com/Chenggou1/fishword" target="_blank" rel="noreferrer">github.com/Chenggou1/fishword</a></td></tr><tr><td><strong>OnePagent</strong></td><td>开源浏览器原生 AI 工作台，打开一个 HTML 文件就能进行 AI 操作</td><td><a href="https://github.com/sligter/OnePagent" target="_blank" rel="noreferrer">github.com/sligter/OnePagent</a></td></tr><tr><td><strong>SlopGuard</strong></td><td>GitHub App，自动为 PR/issue 打质量分，过滤低质量提交</td><td><a href="https://github.com/Blue-B/slopguard" target="_blank" rel="noreferrer">github.com/Blue-B/slopguard</a></td></tr><tr><td><strong>TiyGate</strong></td><td>自建 AI 网关，多个订阅套餐间自动切换，统一管理面板</td><td><a href="https://github.com/tiylabs/tiygate" target="_blank" rel="noreferrer">github.com/tiylabs/tiygate</a></td></tr><tr><td><strong>Mediary Scout</strong></td><td>开源搜剧 Agent，搜索资源存入网盘，需自部署</td><td><a href="https://github.com/fancydirty/mediary-scout" target="_blank" rel="noreferrer">github.com/fancydirty/mediary-scout</a></td></tr></tbody></table><h2 id="内容创作" tabindex="-1">内容创作 <a class="header-anchor" href="#内容创作" aria-label="Permalink to &quot;内容创作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>说明</th><th>链接</th></tr></thead><tbody><tr><td><strong>ai_caption_video</strong></td><td>Windows 开源大字报式中文短视频生成，支持关键词高亮、字幕动效、本地 TTS 配音和语音克隆</td><td><a href="https://github.com/alexchan197611/ai_caption_video" target="_blank" rel="noreferrer">github.com/alexchan197611/ai_caption_video</a></td></tr><tr><td><strong>封面生成器 (Cover Maker)</strong></td><td>网页端封面制作工具</td><td><a href="https://github.com/eternityspring/article-tools" target="_blank" rel="noreferrer">github.com/eternityspring/article-tools</a></td></tr><tr><td><strong>Direct Light</strong></td><td>网页模拟摄影棚灯光效果</td><td><a href="https://github.com/oukeming64-tech/direct-light" target="_blank" rel="noreferrer">github.com/oukeming64-tech/direct-light</a></td></tr></tbody></table><hr><h2 id="值得尝试的" tabindex="-1">值得尝试的 <a class="header-anchor" href="#值得尝试的" aria-label="Permalink to &quot;值得尝试的&quot;">​</a></h2><ul><li><strong>MyKVM</strong>：跨平台键鼠共享，替代硬件 KVM 切换器</li><li><strong>AnyDrag</strong>：macOS 窗口管理，不用点标题栏就能拖拽</li><li><strong>PowerLens</strong>：终端里实时看硬件状态，程序员装逼必备</li><li><strong>SlopGuard</strong>：AI 时代反低质量 PR 的自动化方案</li><li><strong>Lore</strong>：游戏/3D 行业二进制版本管理，Git 的盲区</li></ul>',13)])])}const u=r(d,[["render",i]]);export{c as __pageData,u as default};
